// SPEC LINK: docs/specs/02-web-admin/135_mcfrontend_decisions_register.md FE-16 (Q-MF1 a: all McFrontend specs in docs/specs/02-web-admin; 135 = register,
//            136 = handbook; "135 and 136 exist at the ruled paths once landed") and FE-08 (the doc set; its lock is this one, "see FE-16").
//
// MF-43 · McFrontend queue · lane T. The FE-16 lock. Spec 136 landed with MF-18 (generated by scripts/surfaces/generate-surface-handbook.mjs), so both
// halves are asserted now: each spec exists, tracked, at its ruled path, and no other tracked 135_* or 136_* spec file exists anywhere under docs/specs.
import { describe, expect, it } from 'vitest';
import { spawnSync } from 'node:child_process';

const ROOT = process.cwd();
const SPECS_ROOT = 'docs/specs';
// The ruled paths (Q-MF1 a, Spec 135 status line; 136 named in Spec 135's Role line). Closed.
const RULED: Readonly<Record<string, string>> = {
  '135': 'docs/specs/02-web-admin/135_mcfrontend_decisions_register.md',
  '136': 'docs/specs/02-web-admin/136_mcfrontend_handbook.md',
};
const NUMBERED_RE = /(?:^|\/)(13[56])_[^/]*\.md$/;

function specPathProblems(tracked: readonly string[]): string[] {
  const problems: string[] = [];
  if (tracked.length === 0) return ['no tracked spec file found (dead-man: an empty list never passes)'];
  for (const [n, p] of Object.entries(RULED)) if (!tracked.includes(p)) problems.push(`Spec ${n} is not at its ruled path ${p}`);
  for (const f of tracked) {
    const m = NUMBERED_RE.exec(f);
    if (m?.[1] && f !== RULED[m[1]]) problems.push(`${f}: a Spec ${m[1]} file outside its ruled path ${RULED[m[1]]}`);
  }
  return problems;
}

function trackedSpecs(): string[] {
  const r = spawnSync('git', ['ls-files', SPECS_ROOT], { cwd: ROOT, encoding: 'utf8' });
  expect(r.status).toBe(0);
  return r.stdout.split('\n').filter(Boolean);
}

const REAL = trackedSpecs();

describe('FE-16: Specs 135 and 136 exist at the ruled paths, and nowhere else', () => {
  it('the real tree has no problem', () => {
    expect(specPathProblems(REAL)).toEqual([]);
  });

  it('examined the spec tree (dead-man)', () => {
    expect(REAL.length).toBeGreaterThan(100);
    expect(REAL.filter((f) => NUMBERED_RE.test(f))).toEqual(Object.values(RULED));
  });

  it('planted: a Spec 136 copy under another folder', () => {
    expect(specPathProblems([...REAL, 'docs/specs/03-mobile/136_x.md']).join('\n')).toMatch(/docs\/specs\/03-mobile\/136_x\.md: a Spec 136 file outside its ruled path/);
  });

  it('planted: Spec 135 absent, Spec 136 renamed', () => {
    expect(specPathProblems(REAL.filter((f) => f !== RULED['135'])).join('\n')).toMatch(/Spec 135 is not at its ruled path/);
    const renamed = REAL.map((f) => (f === RULED['136'] ? 'docs/specs/02-web-admin/136_handbook.md' : f));
    const out = specPathProblems(renamed).join('\n');
    expect(out).toMatch(/Spec 136 is not at its ruled path/);
    expect(out).toMatch(/136_handbook\.md: a Spec 136 file outside its ruled path/);
  });

  it('planted: an empty list', () => {
    expect(specPathProblems([]).join('\n')).toMatch(/no tracked spec file found/);
  });
});
